<script lang="ts">
 import { onMount } from 'svelte'; let relances:any[]=[]; let open=false; let editing:any=null; let saving=false; let message=''; let filter='a_faire';
 let form={title:'',type:'client',due_date:'',priority:'normale',notes:''};
 async function load(){const r=await fetch('/api/relances');const b=await r.json();relances=b.relances??[]} onMount(load);
 function create(){editing=null;form={title:'',type:'client',due_date:'',priority:'normale',notes:''};open=true;message=''}
 function edit(r:any){editing=r;form={title:r.title??'',type:r.type??'client',due_date:r.due_date??'',priority:r.priority??'normale',notes:r.notes??''};open=true;message=''}
 async function save(){saving=true;const r=await fetch('/api/relances',{method:editing?'PATCH':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(editing?{id:editing.id,...form}:form)});const b=await r.json();if(!r.ok){message=b.error??'Erreur';saving=false;return}open=false;await load();saving=false}
 async function toggle(r:any){await fetch('/api/relances',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id:r.id,status:r.status==='faite'?'a_faire':'faite'})});await load()}
 async function remove(r:any){if(!confirm('Supprimer cette relance ?'))return;await fetch('/api/relances',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({id:r.id})});await load()}
 $: filtered=relances.filter(r=>filter==='toutes'||r.status===filter);
 $: overdue=relances.filter(r=>r.status==='a_faire'&&r.due_date&&r.due_date<new Date().toISOString().slice(0,10)).length;
 const labels:any={client:'Client',fournisseur:'Fournisseur'};
</script>
<svelte:head><title>ChantierBot — Relances</title></svelte:head>
<div class="space-y-6"><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-xs font-bold uppercase tracking-[.16em] text-primary">Suivi commercial</p><h1 class="text-3xl font-extrabold">Relances</h1><p class="mt-1 text-sm text-ink-secondary dark:text-ink-dark-secondary">Ne laisse plus une demande client ou fournisseur passer à la trappe.</p></div><button class="btn-primary" on:click={create}>＋ Nouvelle relance</button></div>
<div class="grid gap-3 sm:grid-cols-3"><div class="card"><p class="text-xs font-bold uppercase text-slate-500">À faire</p><p class="mt-2 text-3xl font-extrabold">{relances.filter(r=>r.status==='a_faire').length}</p></div><div class="card"><p class="text-xs font-bold uppercase text-red-500">En retard</p><p class="mt-2 text-3xl font-extrabold text-red-600">{overdue}</p></div><div class="card"><p class="text-xs font-bold uppercase text-emerald-600">Terminées</p><p class="mt-2 text-3xl font-extrabold">{relances.filter(r=>r.status==='faite').length}</p></div></div>
<div class="card"><div class="mb-4 flex flex-wrap gap-2">{#each [['a_faire','À faire'],['faite','Terminées'],['toutes','Toutes']] as item}<button class:active={filter===item[0]} class="filter" on:click={()=>filter=item[0]}>{item[1]}</button>{/each}</div>{#if !filtered.length}<div class="py-12 text-center"><div class="text-4xl">🔔</div><h2 class="mt-3 font-bold">Aucune relance</h2><p class="mt-1 text-sm text-ink-secondary">Tout est sous contrôle.</p></div>{:else}<div class="space-y-3">{#each filtered as r}<article class="flex gap-3 rounded-2xl border border-black/5 p-4 dark:border-white/10"><button class="mt-1 h-6 w-6 rounded-full border-2 border-primary" class:bg-primary={r.status==='faite'} on:click={()=>toggle(r)}>{r.status==='faite'?'✓':''}</button><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><h2 class:line-through={r.status==='faite'} class="font-bold">{r.title}</h2><span class="rounded-full bg-primary/10 px-2 py-1 text-xs font-bold text-primary">{labels[r.type]}</span><span class="rounded-full px-2 py-1 text-xs font-bold {r.priority==='urgente'?'bg-red-100 text-red-700':r.priority==='haute'?'bg-amber-100 text-amber-700':'bg-slate-100 text-slate-600'}">{r.priority}</span></div>{#if r.due_date}<p class="mt-1 text-sm {r.status==='a_faire'&&r.due_date<new Date().toISOString().slice(0,10)?'text-red-600 font-bold':'text-ink-secondary'}">📅 {new Date(r.due_date+'T12:00').toLocaleDateString('fr-FR')}</p>{/if}{#if r.notes}<p class="mt-2 text-sm text-ink-secondary">{r.notes}</p>{/if}</div><div class="flex gap-1"><button class="btn-secondary" on:click={()=>edit(r)}>Modifier</button><button class="px-2 text-red-600" on:click={()=>remove(r)}>×</button></div></article>{/each}</div>{/if}</div></div>
{#if open}<div class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4" on:click={(e)=>e.target===e.currentTarget&&(open=false)}><div class="w-full max-w-xl rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900"><div class="flex justify-between"><div><p class="text-xs font-bold uppercase text-primary">{editing?'Modifier':'Nouvelle'}</p><h2 class="text-2xl font-extrabold">Relance</h2></div><button class="text-2xl text-slate-400" on:click={()=>open=false}>×</button></div><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="sm:col-span-2"><span class="label">Objet *</span><input class="input" bind:value={form.title} placeholder="Ex. Relancer pour validation du devis"/></label><label><span class="label">Destinataire</span><select class="input" bind:value={form.type}><option value="client">Client</option><option value="fournisseur">Fournisseur</option></select></label><label><span class="label">Échéance</span><input class="input" type="date" bind:value={form.due_date}/></label><label><span class="label">Priorité</span><select class="input" bind:value={form.priority}><option value="basse">Basse</option><option value="normale">Normale</option><option value="haute">Haute</option><option value="urgente">Urgente</option></select></label><label class="sm:col-span-2"><span class="label">Notes</span><textarea class="input min-h-24" bind:value={form.notes}></textarea></label></div>{#if message}<p class="mt-3 rounded-lg bg-red-50 p-3 text-sm text-red-700">{message}</p>{/if}<div class="mt-6 flex justify-end gap-3"><button class="btn-secondary" on:click={()=>open=false}>Annuler</button><button class="btn-primary" disabled={saving} on:click={save}>{saving?'Enregistrement…':editing?'Enregistrer':'Créer'}</button></div></div></div>{/if}
<style>.filter{border-radius:.75rem;padding:.6rem .9rem;font-size:.875rem;font-weight:700}.filter.active{background:#5865F2;color:white}.input{width:100%;border:1px solid #e2e8f0;border-radius:.75rem;padding:.7rem .8rem;background:inherit;outline:none}.label{display:block;margin-bottom:.4rem;font-size:.8rem;font-weight:700;color:#64748b}:global(.dark) .input{border-color:#334155;background:#0f172a}</style>